// ============================================
// EXTRACT SESSION ID
// ============================================

const input = $input.first().json;
const query = input.query || {};

const sessionId = query.session_id;

if (!sessionId) {
  return {
    error: true,
    error_code: 'MISSING_SESSION_ID',
    message: 'session_id manquant'
  };
}

return {
  error: false,
  session_id: sessionId
};

