// ============================================
// GENERATE SUCCESS HTML PAGE (RFC-003 Branding)
// ============================================

const apiResponse = $('Call API Confirm Checkout').first().json;
const order = apiResponse.order || {};
const branding = apiResponse.branding || {};

// Order data
const orderNumber = order.order_number || 'N/A';
const totalDisplay = order.total_display || '0,00 EUR';
const itemCount = order.item_count || 0;

// Branding data with defaults
const brandName = branding.name || 'Bot Appetit';
const logoUrl = branding.logo_url || '';
const primaryColor = branding.primary_color || '#10B981';
const discordUrl = branding.discord_url || 'https://discord.com/channels/@me';

// Logo HTML (only if URL provided)
const logoHtml = logoUrl 
  ? `<img src="${logoUrl}" alt="${brandName}" style="max-width: 120px; max-height: 80px; margin-bottom: 16px;">` 
  : '';

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Paiement confirmé - ${brandName}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .card {
      background: white;
      border-radius: 16px;
      padding: 40px;
      max-width: 450px;
      width: 100%;
      text-align: center;
      box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    }
    .logo {
      margin-bottom: 16px;
    }
    .icon {
      width: 80px;
      height: 80px;
      background: ${primaryColor};
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
    }
    .icon svg {
      width: 40px;
      height: 40px;
      fill: white;
    }
    h1 {
      color: #1F2937;
      font-size: 24px;
      margin-bottom: 16px;
    }
    p {
      color: #6B7280;
      font-size: 16px;
      line-height: 1.6;
      margin-bottom: 24px;
    }
    .brand-name {
      color: ${primaryColor};
      font-weight: 600;
    }
    .order-info {
      background: #F3F4F6;
      border-radius: 12px;
      padding: 20px;
      margin-bottom: 24px;
    }
    .order-row {
      display: flex;
      justify-content: space-between;
      padding: 8px 0;
      border-bottom: 1px solid #E5E7EB;
    }
    .order-row:last-child {
      border-bottom: none;
    }
    .order-label {
      color: #6B7280;
      font-size: 14px;
    }
    .order-value {
      color: #1F2937;
      font-weight: 600;
      font-size: 14px;
    }
    .btn {
      display: inline-block;
      background: ${primaryColor};
      color: white;
      text-decoration: none;
      padding: 14px 28px;
      border-radius: 8px;
      font-weight: 600;
      font-size: 16px;
      transition: opacity 0.2s;
    }
    .btn:hover {
      opacity: 0.9;
    }
    .notice {
      margin-top: 20px;
      padding: 12px;
      background: #ECFDF5;
      border-radius: 8px;
      font-size: 13px;
      color: #065F46;
    }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo">${logoHtml}</div>
    <div class="icon">
      <svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>
    </div>
    <h1>Paiement confirmé !</h1>
    <p>Merci pour votre commande sur <span class="brand-name">${brandName}</span>.</p>
    <div class="order-info">
      <div class="order-row">
        <span class="order-label">Commande</span>
        <span class="order-value">${orderNumber}</span>
      </div>
      <div class="order-row">
        <span class="order-label">Articles</span>
        <span class="order-value">${itemCount} article(s)</span>
      </div>
      <div class="order-row">
        <span class="order-label">Total</span>
        <span class="order-value">${totalDisplay}</span>
      </div>
    </div>
    <a href="${discordUrl}" class="btn">Retourner sur Discord</a>
    <div class="notice">Un message de confirmation a été envoyé sur Discord.</div>
  </div>
</body>
</html>`;

return { html, branding };

